<?php namespace App\Services; use App\Models\Product; use App\Models\Purchase; use Illuminate\Support\Facades\DB; class RecordPurchaseService { public function record(array $data,?int $userId):Purchase{return DB::transaction(function()use($data,$userId){$total='0.00';$lines=[];foreach($data['items'] as $item){$product=Product::lockForUpdate()->findOrFail($item['product_id']);$line=Money::mul((string)$item['quantity'],(string)$item['cost_price']);$total=Money::add($total,$line);$lines[]=[$product,$item,$line];}$purchase=Purchase::create(['supplier_name'=>$data['supplier_name'],'purchase_date'=>$data['purchase_date'],'payment_status'=>$data['payment_status'],'notes'=>$data['notes']??null,'total_amount'=>$total,'user_id'=>$userId]);foreach($lines as [$product,$item,$line]){$purchase->items()->create(['product_id'=>$product->id,'quantity'=>$item['quantity'],'cost_price'=>$item['cost_price'],'line_total'=>$line]);$product->update(['stock_quantity'=>bcadd($product->stock_quantity,(string)$item['quantity'],3),'cost_price'=>$item['cost_price']]);}return $purchase->load('items.product');});} }